        ],
        'query' =&gt; [
            'page' =&gt; '1',
            'limit' =&gt; '10',
            'search' =&gt; 'Nguyen',
            'status' =&gt; 'Active',
        ],
    ]
);
$body = $response-&gt;getBody();
