                'contents' =&gt; '2024-06-01 10:00:00'
            ],
            [
                'name' =&gt; 'ImageUrl',
                'contents' =&gt; fopen('C:\Users\ACER\AppData\Local\Temp\php86C7.tmp', 'r')
            ],
        ],
    ]
);
$body = $response-&gt;getBody();
print_r(json_decode((string) $body));</code></pre></div>


