            'Type' =&gt; 'System',
            'IsRead' =&gt; true,
            'Status' =&gt; 'ydlsmsjuryvojcybz',
            'Link' =&gt; '/profile',
        ],
    ]
);
$body = $response-&gt;getBody();
print_r(json_decode((string) $body));</code></pre></div>


