        ],
        'json' =&gt; [
            'Name' =&gt; 'Universal Pictures Updated',
            'MovieId' =&gt; 17,
            'Country' =&gt; 'United States',
            'Email' =&gt; 'contact@universalpictures.com',
            'Phone' =&gt; '+1 123-456-7890',
            'Website' =&gt; 'https://www.universalpictures.com',
            'Status' =&gt; 'Inactive',
