    --header "Content-Type: application/json" \
    --data "{
    \"MovieId\": 1,
    \"RoomId\": 1,
    \"StartDate\": \"2024-01-01\",
    \"EndDate\": \"2024-01-31\",
    \"DaysOfWeek\": [
        \"Sat\"
    ],
    \"StartTime\": \"07:14\",
    \"EndTime\": \"2107-09-02\",
    \"Price\": \"120000\",
    \"Status\": \"Active\",
    \"CinemaId\": 1,
    \"Showtimes\": [
        \"10:00\",
        \"13:00\",
        \"16:00\"
    ]
}"
</code></pre></div>


